#include <vector>
#include <string>
#include <unordered_map>
#include <algorithm>

struct TrieNode {
    std::unordered_map<char, TrieNode*> next;
};

class Solution {
public:
    int minValidStrings(std::vector<std::string>& words, std::string target) {
        TrieNode* root = new TrieNode();
        for (const auto& w : words) {
            TrieNode* curr = root;
            for (char ch : w) {
                if (!curr->next.count(ch)) curr->next[ch] = new TrieNode();
                curr = curr->next[ch];
            }
        }

        int n = target.size();
        std::vector<int> max_jump(n, 0);
        for (int i = 0; i < n; ++i) {
            TrieNode* curr = root;
            int len = 0;
            for (int j = i; j < n; ++j) {
                char ch = target[j];
                if (!curr->next.count(ch)) break;
                curr = curr->next[ch];
                len++;
            }
            max_jump[i] = len;
        }

        int jumps = 0, curr_end = 0, farthest = 0;
        for (int i = 0; i < n; ++i) {
            farthest = std::max(farthest, i + max_jump[i]);
            if (i == curr_end) {
                if (farthest == curr_end) return -1;
                jumps++;
                curr_end = farthest;
                if (curr_end >= n) return jumps;
            }
        }
        return curr_end >= n ? jumps : -1;
    }
};

import java.util.*;

class Solution {
    static class TrieNode {
        Map<Character, TrieNode> next = new HashMap<>();
    }

    public int minValidStrings(String[] words, String target) {
        TrieNode root = new TrieNode();
        for (String w : words) {
            TrieNode curr = root;
            for (char ch : w.toCharArray()) {
                curr.next.putIfAbsent(ch, new TrieNode());
                curr = curr.next.get(ch);
            }
        }

        int n = target.length();
        int[] maxJump = new int[n];
        for (int i = 0; i < n; i++) {
            TrieNode curr = root;
            int len = 0;
            for (int j = i; j < n; j++) {
                char ch = target.charAt(j);
                if (!curr.next.containsKey(ch)) break;
                curr = curr.next.get(ch);
                len++;
            }
            maxJump[i] = len;
        }

        int jumps = 0, currEnd = 0, farthest = 0;
        for (int i = 0; i < n; i++) {
            farthest = Math.max(farthest, i + maxJump[i]);
            if (i == currEnd) {
                if (farthest == currEnd) return -1;
                jumps++;
                currEnd = farthest;
                if (currEnd >= n) return jumps;
            }
        }
        return currEnd >= n ? jumps : -1;
    }
}

var minValidStrings = function(words, target) {
    const root = {};
    for (const w of words) {
        let curr = root;
        for (let i = 0; i < w.length; i++) {
            const ch = w[i];
            if (!curr[ch]) curr[ch] = {};
            curr = curr[ch];
        }
    }

    const n = target.length;
    const maxJump = new Int32Array(n);
    for (let i = 0; i < n; i++) {
        let curr = root;
        let len = 0;
        for (let j = i; j < n; j++) {
            const ch = target[j];
            if (!curr[ch]) break;
            curr = curr[ch];
            len++;
        }
        maxJump[i] = len;
    }

    let jumps = 0, currEnd = 0, farthest = 0;
    for (let i = 0; i < n; i++) {
        if (i + maxJump[i] > farthest) farthest = i + maxJump[i];
        if (i === currEnd) {
            if (farthest === currEnd) return -1;
            jumps++;
            currEnd = farthest;
            if (currEnd >= n) return jumps;
        }
    }
    return currEnd >= n ? jumps : -1;
};
